function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function save(){try{localStorage.setItem('shiyu.v1',JSON.stringify(saved));}catch{toast('浏览器未允许保存进度，本次仍可体验。');}}
function cleanup(){stop();clearTimeout(practiceTimer);homeMotionCleanup?.();homeMotionCleanup=null;playing=false;recording=null;agent.controller?.abort();agent.request++;agent.upload++;agent.busy=false;voiceRecognition?.abort?.();voiceRecognition=null;agent.listening=false;window.speechSynthesis?.cancel();}
function go(id){if(id==='dance')id='drums';if(!nav.some(x=>x[0]===id))return;cleanup();page=id;history.replaceState(null,'','#'+id);if(!saved.visits.includes(id)){saved.visits.push(id);save();}render();window.scrollTo({top:0,behavior:'instant'});}
function render(){
 const isHome=page==='home';
 const isHistory=page==='history';
 const isCraft=page==='craft';
 const isDrums=page==='drums';
 const isAgent=page==='agent';
 document.body.classList.toggle('home-active',isHome);
 document.body.classList.toggle('history-active',isHistory);
 document.body.classList.toggle('craft-active',isCraft);
 document.body.classList.toggle('drums-active',isDrums);
 document.body.classList.toggle('agent-active',isAgent);
 const header=`<header class="${isHome?'home-header':isHistory?'history-header':isCraft?'craft-header':''}"><div class="masthead"><a class="brand" href="#home"><span class="seal">狮</span><span><strong>狮遇</strong><small>LION & LEGACY</small></span></a><p>让非遗，被看见、被听见。</p><button class="agent-shortcut" data-page="agent"><i></i> AI 非遗导览 <span>↗</span></button></div><nav aria-label="主导航">${nav.map(([id,name],i)=>`<button data-page="${id}" ${page===id?'aria-current="page"':''}><span class="nav-no">0${i+1}</span>${name}</button>`).join('')}</nav></header>`;
 $('#app').innerHTML=`${header}<main id="main" class="${isHome?'home-main':isHistory?'history-main':isCraft?'craft-main':isAgent?'agent-main':''}" tabindex="-1">${({home,history:historyPage,craft:craftPage,drums:drumsPage,agent:agentPage})[page]()}</main><footer class="${isHome?'home-footer':isHistory?'history-footer':isCraft?'craft-footer':''}"><span>狮遇 <em>·</em> 数字非遗互动馆</span><span>以形识狮，以声入境。</span>${button('作品与资料 ↗','sources','text-button')}</footer>`;
 if(isHistory)$('#main').insertAdjacentHTML('beforeend',regionalArchive());
 if(isHome){$('.jack-about .about-cta')?.insertAdjacentHTML('beforebegin',legendArchive());initHomeMotion();const motionCleanup=homeMotionCleanup,legendCleanup=initLegendCards();homeMotionCleanup=()=>{motionCleanup?.();legendCleanup?.();};}
 if(isHistory){const historyCleanup=initHistoryTimeline(),regionCleanup=initRegionalCards();homeMotionCleanup=()=>{historyCleanup?.();regionCleanup?.();};}
 if(page==='drums')initDrumCulture();
 if(page==='agent'&&configured===null)fetch('/api/lion-agent/status').then(r=>r.json()).then(v=>{configured=!!v.configured;signedIn=!!v.signedIn;if(page==='agent'&&$('#signin-note'))$('#signin-note').hidden=signedIn;if(page==='agent'&&$('#agent-status'))$('#agent-status').textContent=configured?'文字 · 图片 · 浏览器语音转文字':'AI 暂未配置，仍可检索资料';}).catch(()=>{});
}
function legendArchive(){return `<section class="lion-legends reveal" aria-labelledby="legend-title"><div class="legend-heading"><span>COLOR &amp; CHARACTER</span><h3 id="legend-title">六色英雄狮</h3><p>六张卡牌将从中央展开。点击一只狮子，阅读它的角色、色彩与民俗寓意。</p></div><div class="legend-stack" id="legend-stack">${legendLions.map((x,i)=>`<button class="legend-card" data-action="lion-legend" data-index="${i}" style="--accent:${x.color};--lion-image:url('${x.image}')" aria-label="查看${x.name}知识文档"><span class="legend-number">0${i+1}</span><span class="legend-face" aria-hidden="true"></span><span class="legend-meta"><small>${x.alias}</small><b>${x.name}</b><em>${x.symbol}</em></span></button>`).join('')}</div><p class="legend-hint">点击卡牌查看知识文档 <span>CLICK TO READ ↗</span></p></section><dialog class="lion-dialog" id="lion-dialog" aria-labelledby="legend-dialog-title"><button class="dialog-close" data-action="close-legend" aria-label="关闭知识文档">×</button><article><div class="dialog-visual"><span class="legend-face" id="dialog-face"></span><span id="dialog-number">01</span></div><div class="dialog-copy"><span id="dialog-alias">黄狮</span><h2 id="legend-dialog-title">刘备狮</h2><p class="dialog-symbol" id="dialog-symbol"></p><p id="dialog-text"></p><small>民俗寓意随地区、狮队与传承传统有所差异。</small></div></article></dialog>`;}
function home(){const experiences=[['history','01','历史简介','循时间认识狮舞的来处与当代传承'],['regions','02','地区狮舞','从轮廓、眉眼与嘴形辨认地方狮貌'],['craft','03','制作工艺','走完扎、扑、写、装四道狮头工序'],['drums','04','鼓点互动','亲手敲击，让醒狮随节奏起舞'],['agent','05','多模态 Agent','上传狮头图片，追问一段非遗故事']];return `<section class="jack-hero" aria-label="狮遇首屏"><div class="jack-title" aria-hidden="true"><span>中国</span><span>舞狮</span></div><div class="jack-lion"><span class="jack-aura"></span><img src="/lion/lion-black-red.jpg" alt="黑红配色的醒狮狮头特写" fetchpriority="high"></div><div class="jack-copy"><p>AN INTERACTIVE ARCHIVE OF<br>CHINESE LION DANCE.</p><span>看见狮艺的形，听见非遗的声。</span></div>${button('击鼓唤醒醒狮 <span>↗</span>','start-drums','jack-cta')}<div class="scroll-mark"><i></i><span>SCROLL TO EXPLORE</span></div></section><section class="jack-showcase"><div class="showcase-grid">${[['regions','REGIONAL LIONS','一方水土，一方狮'],['craft','CRAFT','竹骨纸衣，笔下传神'],['drums','RHYTHM','以鼓为令，以声传情'],['agent','MULTIMODAL AI','图像识狮，资料有据']].map(([id,en,cn],i)=>`<button class="showcase-card reveal card-${i+1}" data-page="${id}"><span>0${i+1}</span><div><small>${en}</small><h2>${cn}</h2></div><b>↗</b></button>`).join('')}</div></section><section class="jack-about reveal"><span class="float-mark mark-one">◉</span><span class="float-mark mark-two">✦</span><span class="float-mark mark-three">福</span><h2>ABOUT LION</h2><p>狮舞不只是一场表演。它把工艺、节奏、身体与祝福连在一起。<br>在这里，从观看开始，以一次亲手参与完成认识。</p>${button('进入 AI 导览','start-agent','jack-cta about-cta')}</section><section class="jack-experiences"><h2 class="reveal">EXPERIENCES</h2><div class="experience-list">${experiences.map(([id,n,title,desc])=>`<button class="experience-row reveal" data-page="${id}"><strong>${n}</strong><span><b>${title}</b><small>${desc}</small></span><i>↗</i></button>`).join('')}</div></section><section class="jack-projects"><h2 class="reveal">EXPLORE</h2><div class="project-stack">${[['regions','01','REGIONAL','五种地方狮貌'],['drums','02','RHYTHM INTERACTION','击鼓唤醒醒狮'],['agent','03','MULTIMODAL AGENT','图像识狮与资料增强']].map(([id,n,en,cn])=>`<button class="project-card reveal" data-page="${id}"><strong>${n}</strong><span><small>${en}</small>${cn}</span><b>OPEN ↗</b></button>`).join('')}</div></section><details id="work-note" class="work-note jack-note"><summary>作品说明与资料出处 <span>＋</span></summary><div><h2>狮遇 · 非遗舞狮多模态互动馆</h2><p>通过历史、地区形象、制作工艺、鼓点互动和多模态 Agent，把“观看—理解—动手—反馈”连接为一次体验。进度与数字狮头配色保存在当前浏览器。</p><p>本站狮头为原创矢量教学示意；鼓点为原创合成节奏。地方传统各有差异，图像识别会给出依据与不确定性。AI 可检索资料并调用工具，打开对应地区、工艺或鼓点画面。</p><div class="source-list">${Object.keys(sources).map(ref).join('')}</div></div></details>`;}
function initHomeMotion(){const hero=$('.jack-hero'),lion=$('.jack-lion'),title=$('.jack-title');if(!hero||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const move=e=>{const r=hero.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;lion?.style.setProperty('--mx',`${x*18}px`);lion?.style.setProperty('--my',`${y*12}px`);title?.style.setProperty('--tx',`${x*-7}px`);title?.style.setProperty('--ty',`${y*-4}px`);};const leave=()=>{lion?.style.setProperty('--mx','0px');lion?.style.setProperty('--my','0px');title?.style.setProperty('--tx','0px');title?.style.setProperty('--ty','0px');};hero.addEventListener('pointermove',move);hero.addEventListener('pointerleave',leave);const observer=new IntersectionObserver(entries=>entries.forEach(x=>{if(x.isIntersecting)x.target.classList.add('in-view');}),{threshold:.15});$$('.reveal').forEach(x=>observer.observe(x));homeMotionCleanup=()=>{hero.removeEventListener('pointermove',move);hero.removeEventListener('pointerleave',leave);observer.disconnect();};}
function initLegendCards(){const stage=$('#legend-stack'),cards=$$('.legend-card'),dialog=$('#lion-dialog');if(!stage)return()=>{};const positions=cards.map((_,i)=>({x:(i-2.5)*188,y:Math.abs(i-2.5)*18,r:(i-2.5)*5}));const spread=()=>{if(stage.dataset.spread)return;stage.dataset.spread='1';if(innerWidth<720||matchMedia('(prefers-reduced-motion: reduce)').matches){stage.classList.add('mobile-grid');cards.forEach(x=>{x.style.opacity='1';x.style.transform='none';});return;}if(window.anime)window.anime({targets:cards,translateX:(el,i)=>positions[i].x,translateY:(el,i)=>positions[i].y,rotate:(el,i)=>positions[i].r,scale:[.82,1],opacity:[.4,1],duration:1050,easing:'easeOutBack',delay:window.anime.stagger(95)});else cards.forEach((card,i)=>card.animate([{transform:'translate(0,0) rotate(0deg) scale(.82)',opacity:.4},{transform:`translate(${positions[i].x}px,${positions[i].y}px) rotate(${positions[i].r}deg) scale(1)`,opacity:1}],{duration:1050,delay:i*95,easing:'cubic-bezier(.2,.8,.2,1)',fill:'forwards'}));};const observer=new IntersectionObserver(entries=>entries.forEach(x=>{if(x.isIntersecting){spread();observer.disconnect();}}),{threshold:.28});observer.observe(stage);const unlock=()=>{document.body.style.overflow='';};const backdrop=e=>{if(e.target===dialog)dialog.close();};dialog?.addEventListener('close',unlock);dialog?.addEventListener('click',backdrop);return()=>{observer.disconnect();dialog?.removeEventListener('close',unlock);dialog?.removeEventListener('click',backdrop);unlock();};}
function openLegend(i){const x=legendLions[i],dialog=$('#lion-dialog');if(!x||!dialog)return;const face=$('#dialog-face');face.style.setProperty('--lion-image',`url('${x.image}')`);face.style.setProperty('--accent',x.color);$('#dialog-number').textContent=`0${i+1}`;$('#dialog-alias').textContent=x.alias;$('#dialog-alias').style.color=x.color;$('#legend-dialog-title').textContent=x.name;$('#dialog-symbol').textContent=x.symbol;$('#dialog-text').textContent=x.text;document.body.style.overflow='hidden';if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','');}
function historyPage(){return `<section class="history-hero"><div class="history-hero-copy"><span>01 / HISTORY OF LINGNAN LION</span><h1>岭南醒狮<br><em>千年一脉</em></h1><p>从瑞兽想象到非遗新生，沿着一条时间主线，阅读醒狮如何走入岭南、走向世界。</p></div><div class="history-hero-mark" aria-hidden="true"><b>醒</b><i></i><small>LION<br>LEGACY</small></div><img class="history-hero-lion" src="/lion/history-lion-cutout.webp" alt="红白岭南醒狮昂首跃起的立体形象"><div class="history-scroll"><i></i><span>SCROLL TO TRACE</span></div></section><section class="history-timeline" aria-label="岭南醒狮历史时间轴"><div class="history-line" aria-hidden="true"><i></i></div>${timeline.map((t,i)=>`<article class="history-node ${i%2?'node-right':'node-left'} ${t.featured?'featured':''}"><div class="history-card" tabindex="0" aria-describedby="history-detail-${i}"><span class="history-no">0${i+1}</span><p>${esc(t.era)}</p><h2>${esc(t.title)}</h2><div class="history-rule"></div><p class="history-summary">${esc(t.summary)}</p><small>HOVER TO READ <b>↗</b></small></div><span class="history-dot" aria-hidden="true"><i></i></span><aside class="history-popover" id="history-detail-${i}" role="tooltip"><span>${esc(t.era)} · 详细讲解</span><h3>${esc(t.title)}</h3><p>${esc(t.detail)}</p></aside></article>`).join('')}<p class="history-note">时间线以通俗叙事呈现醒狮发展脉络；不同地区、流派与传承体系仍存在差异。</p></section>`;}
function regionalArchive(){return `<section id="regional-lions" class="regional-archive" aria-labelledby="regional-title"><div class="regional-heading"><span class="eyebrow">02 / REGIONAL LION DANCE</span><h2 id="regional-title">大江南北，狮影万千</h2><p>同是醒狮，一方水土，铸一方狮魂。南北流派各领风华，脸谱、招式、鼓点自成一派，每一头雄狮，都藏着独属于这片土地的热血与信仰。</p></div><div class="regional-grid">${regions.map((r,i)=>`<details id="region-${r.id}" class="region-card reveal ${r.featured?'featured':''}"><summary><img src="${r.image}" alt="${r.name}舞狮照片" loading="lazy"><span class="region-shade"></span><span class="region-number">0${i+1} <i>${r.en}</i></span><span class="region-card-copy"><small>${r.place}</small><b>${r.name}</b><em>${r.quick}</em><span class="region-hint">悬停 / 点击 查看介绍 <i>↗</i></span></span></summary><div class="region-popover"><span>${r.kind}</span><b>${r.quick}</b><p>${r.body}</p></div></details>`).join('')}</div><p class="regional-note">配图为图像模型生成的文化展示影像；各地流派在不同传承中也会有所变化。</p></section>`;}
function initRegionalCards(){const cards=$$('.regional-archive .region-card');if(!cards.length)return()=>{};const observer=new IntersectionObserver(entries=>entries.forEach(x=>{if(x.isIntersecting)x.target.classList.add('is-visible');}),{threshold:.12,rootMargin:'0px 0px -5%'});cards.forEach(x=>observer.observe(x));return()=>observer.disconnect();}
function initHistoryTimeline(){const section=$('.history-timeline'),nodes=$$('.history-node');if(!section)return()=>{};const observer=new IntersectionObserver(entries=>entries.forEach(x=>{if(x.isIntersecting)x.target.classList.add('is-visible');}),{threshold:.18,rootMargin:'0px 0px -8%'});nodes.forEach(x=>observer.observe(x));const update=()=>{const r=section.getBoundingClientRect(),start=innerHeight*.72,end=innerHeight*.25,travel=r.height+start-end,progress=Math.max(0,Math.min(1,(start-r.top)/travel));section.style.setProperty('--history-progress',progress);};addEventListener('scroll',update,{passive:true});update();return()=>{observer.disconnect();removeEventListener('scroll',update);};}
const craftColors=[['#a81722','朱砂红'],['#285b72','石青'],['#d3a64f','石黄'],['#262321','墨黑']];
const craftParts=[['eyes','狮眼','双目传神'],['pompom','绒球','眉心点睛'],['mirror','额镜','额间饰镜'],['whiskers','胡须','须髯添势'],['fur','绒毛','沿边收饰']];
const heroTemplates=[['刘备狮','#d7aa40','#7e1d20'],['马超狮','#397da5','#d7c999'],['赵云狮','#478454','#d8bc65'],['关公狮','#a81722','#d9b35e'],['张飞狮','#292929','#b6a67b'],['黄忠狮','#cf7134','#e6bd62']];
function craftPartsMarkup(){return craftParts.map(([id])=>{if(!installedParts.has(id))return'';if(id==='eyes')return `<g class="part-installed"><ellipse cx="220" cy="230" rx="40" ry="34" fill="#f5e9cf" stroke="#d8b769" stroke-width="8"/><ellipse cx="380" cy="230" rx="40" ry="34" fill="#f5e9cf" stroke="#d8b769" stroke-width="8"/><circle cx="220" cy="230" r="19" fill="#28231f"/><circle cx="380" cy="230" r="19" fill="#28231f"/><circle cx="214" cy="224" r="6" fill="white"/><circle cx="374" cy="224" r="6" fill="white"/></g>`;if(id==='pompom')return `<g class="part-installed"><circle cx="300" cy="155" r="24" fill="#c59d49" stroke="#f0d48c" stroke-width="5"/><circle cx="300" cy="155" r="10" fill="#a81722"/></g>`;if(id==='mirror')return `<g class="part-installed"><path d="M300 70l13 13 18 4-18 5-13 13-5-13-18-5 18-4Z" fill="#e5c779" stroke="#fff0bf" stroke-width="3"/><circle cx="300" cy="88" r="8" fill="#f9e8b0"/></g>`;if(id==='whiskers')return `<g class="part-installed" fill="none" stroke="#eee1c7" stroke-width="5" stroke-linecap="round"><path d="M262 300q-52-20-81 4m81 2q-49 0-68 25m104-31q52-20 81 4m-81 2q49 0 68 25"/></g>`;return `<g class="part-installed" fill="none" stroke="#e8d4a2" stroke-width="12" stroke-linecap="round"><path d="M120 145q-22-34-31-9m57-32q-18-37-5-43m55 62q-8-40 9-49m218 71q22-34 31-9m-57-32q18-37 5-43m-55 62q8-40-9-49M145 355q-20 32-4 48m73-29q-5 37 13 47m145-66q20 32 4 48m-73-29q5 37-13 47"/></g>`;}).join('');}
function craftIllustration(){const frame=`<g class="bamboo-frame" fill="none" stroke="#bd9a5e" stroke-width="7" stroke-linecap="round"><title>悬停查看竹篾受力骨与轮廓骨示意</title><path d="M110 145Q190 42 300 70Q410 42 490 145L467 300Q430 393 300 410Q170 393 133 300Z"/><ellipse cx="300" cy="235" rx="130" ry="160"/><ellipse cx="300" cy="235" rx="58" ry="160"/><path d="M115 155q185 70 370 0M130 220h340M136 285q164-45 328 0M160 340q140-62 280 0M300 70v340M135 153q-38-52-80-45l28 67m382-22q38-52 80-45l-28 67"/><path d="M262 298q38-28 76 0m-63 20q25 20 50 0"/></g><g class="tie-marks" fill="#a81722"><circle cx="300" cy="71" r="7"/><circle cx="134" cy="155" r="7"/><circle cx="466" cy="155" r="7"/><circle cx="300" cy="410" r="7"/></g>`;const shell=`<path class="paper-shell" d="M112 151Q106 101 164 117Q205 43 300 72Q395 43 436 117Q494 101 488 151L466 300Q445 385 300 405Q155 385 134 300Z"/>`;const paint=`<path d="M142 163Q300 95 458 163" fill="none" stroke="var(--craft-accent)" stroke-width="14"/><path d="M153 179l-26-39 47 27m273 12 26-39-47 27" fill="none" stroke="var(--craft-ink)" stroke-width="9"/><path d="M194 163q106-53 212 0l-22 30q-84-30-168 0Z" fill="var(--craft-accent)"/><path d="M178 317q122 48 244 0l-23 40q-99 39-198 0Z" fill="var(--craft-ink)"/><path d="M246 279q54-29 108 0l-9 23q-45 16-90 0Z" fill="var(--craft-accent)"/>`;
const zones=craft===3?craftParts.map(([id,label])=>installedParts.has(id)?'':`<g class="drop-zone" data-slot="${id}" tabindex="0" role="button" aria-label="放置${label}"><circle cx="${{eyes:300,pompom:300,mirror:300,whiskers:300,fur:300}[id]}" cy="${{eyes:230,pompom:155,mirror:88,whiskers:318,fur:385}[id]}" r="${id==='eyes'?66:id==='fur'?32:27}"/><text x="300" y="${{eyes:238,pompom:163,mirror:96,whiskers:326,fur:393}[id]}">${label}</text></g>`).join(''):'';
const strokes=craftDrawing.map(s=>`<path d="${s.points}" fill="none" stroke="${s.color}" stroke-width="${s.width}" stroke-linecap="round" stroke-linejoin="round"/>`).join('');
return `<svg id="craft-illustration" class="craft-illustration step-${craft}" viewBox="0 0 600 500" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${['竹篾狮头骨架','逐层裱纸的狮头','可手绘彩纹的狮头纸胚','等待装饰的醒狮狮头'][craft]}"><style>.paper-shell{fill:#dfd2b8;stroke:#b99a69;stroke-width:5}.step-0 .paper-shell{display:none}.step-1 .paper-shell{fill:#e8dcc5;opacity:${Math.min(1,progress/4)}}.step-2 .paper-shell,.step-3 .paper-shell{fill:var(--craft-base);opacity:1}.step-0 .bamboo-frame{stroke-dasharray:1200;stroke-dashoffset:1200;animation:craft-grow 2.4s ease-out forwards}.step-1 .bamboo-frame{opacity:.38}.step-2 .bamboo-frame,.step-3 .bamboo-frame{opacity:.16}.paint-marks{display:${craft>=2?'block':'none'}}.drop-zone circle{fill:#c8a5681a;stroke:#d8bd83;stroke-width:2;stroke-dasharray:6 5}.drop-zone text{fill:#d5bf8c;font:11px sans-serif;text-anchor:middle}.drop-zone{cursor:pointer}.part-installed{filter:drop-shadow(0 4px 5px #0006)}@keyframes craft-grow{to{stroke-dashoffset:0}}@media(prefers-reduced-motion:reduce){.step-0 .bamboo-frame{animation:none;stroke-dashoffset:0}}</style><defs><radialGradient id="craft-glow"><stop stop-color="#b5262d" stop-opacity=".22"/><stop offset="1" stop-color="#b5262d" stop-opacity="0"/></radialGradient></defs><ellipse cx="300" cy="248" rx="252" ry="225" fill="url(#craft-glow)"/>${craft===0?frame:frame+shell+(craft>=2?`<g class="paint-marks">${paint}</g>`:'')}${craft<2?'':`<g class="drawing-layer" pointer-events="none">${strokes}</g>`}${craft===3?`${craftPartsMarkup()}${zones}`:''}<ellipse cx="300" cy="445" rx="150" ry="13" fill="#000" opacity=".24"/></svg>`;}
function craftPage(){const c=craftSteps[craft],notes=['竹篾交错撑起狮头的额、眼、鼻与下颌。选中骨架线，可辨认轮廓骨与支撑骨。','“扑”是把纸料逐层裱到骨架上。拖动层数，观察骨架如何变成完整纸胚。','师傅把狮头彩绘称作“写狮”。选色后直接在纸胚上落笔，也可套用六款人物狮配色。','把五件装饰放入对应位置；全部归位后，就能保存自己的狮头 PNG。'];return `<section class="craft-page"><div class="craft-heading"><span class="eyebrow">03 / CRAFT · MAKING A LION HEAD</span><h1>一只狮头的诞生</h1><p>从一把竹篾开始，亲手完成一只醒狮。</p></div><div class="craft-tabs" role="tablist" aria-label="狮头制作工序">${craftSteps.map((x,i)=>button(`<b>${x.word}</b><span>0${i+1}　${x.name}</span>`,'craft',i===craft?'selected':'',`data-index="${i}" aria-pressed="${i===craft}" role="tab"`)).join('')}</div><section class="craft-studio"><div class="craft-stage-wrap"><div class="craft-stage-top"><span>0${craft+1} / 04 <i>·</i> ${c.name}</span><span class="craft-mini-note">${craft===0?'竹骨生长中':craft===1?`裱纸 ${progress} / 5 层`:craft===2?'笔墨可落':'待装饰'}</span></div><div id="craft-canvas" class="craft-visual" style="--craft-ink:${craftInk};--craft-accent:${palette.accent};--craft-base:${craft===3?palette.color:craft===2?(craftTemplate>=0?palette.color:'#f1eadb'):'#d9cbb0'}">${craftIllustration()}${craft===2?`<p class="draw-tip">在狮头纸胚上按住绘制 · 试试画眉纹</p>`:''}${craft===3&&installedParts.size===5?`<div class="craft-complete-mark">醒狮已成 · 可以带走</div>`:''}</div><div class="craft-stage-footer"><span>岭南醒狮扎作 · 交互教学示意</span><span>${craft===2?'拖动落笔':craft===3?`${installedParts.size} / 5 件归位`:'过程会因流派与师承有所不同'}</span></div></div><aside class="craft-panel"><div class="craft-panel-top"><span class="eyebrow">${c.material}</span><span class="craft-step-count">${String(craft+1).padStart(2,'0')} — 04</span></div><h2>${c.name}</h2><p class="craft-detail">${c.detail}</p><p class="craft-instruction">${notes[craft]}</p>${craft===0?`<div class="craft-material"><small>本步材料</small><b>竹篾</b><b>细绳</b><span>承重骨架 · 轮廓骨</span></div><div class="craft-lore" title="民俗知识提示：狮头工艺与寓意因地区、作坊和师承各有差异。"><span>✦</span><p>骨架决定狮头的比例，也藏着外表看不见的扎作功夫。</p></div>`:''}${craft===1?`<label class="range-label craft-range">裱纸层数 <output id="paper-value">${progress} 层</output><input id="paper-progress" aria-label="调整裱纸层数" type="range" min="0" max="5" step="1" value="${progress}"></label><div class="paper-count">${[1,2,3,4,5].map(n=>`<i class="${n<=progress?'on':''}"></i>`).join('')}<span>逐层覆盖骨架</span></div><div class="craft-lore" title="民俗知识提示：狮头工艺与寓意因地区、作坊和师承各有差异。"><span>✦</span><p>纸层厚薄会影响狮头的轻重与耐用度；实际材料和层数随作坊而异。</p></div>`:''}${craft===2?`<div class="paint-tools"><div class="craft-color-row">${craftColors.map(([color,name])=>`<button class="paint-swatch ${craftInk===color?'active':''}" data-action="craft-ink" data-color="${color}" aria-label="选${name}" title="${name}"><i style="--swatch:${color}"></i><span>${name}</span></button>`).join('')}</div><div class="template-head"><small>五虎人物狮配色</small><button class="text-button" data-action="clear-paint">清除笔迹</button></div><div class="hero-template-grid">${heroTemplates.map(([name,color,accent],i)=>`<button data-action="craft-template" data-index="${i}" class="hero-template ${craftTemplate===i?'active':''}"><i style="--template:${color}"></i>${name.replace('狮','')}</button>`).join('')}</div></div><div class="craft-lore" title="民俗知识提示：狮头工艺与寓意因地区、作坊和师承各有差异。"><span>✦</span><p>传统狮头的颜色与纹样会因流派、作坊而异；刘备、关公等人物原型是部分佛山狮头的传承特色。</p></div>`:''}${craft===3?`<div class="assembly-head"><span>选择零件，拖到狮头的虚线位置</span><small>错位会弹回原处</small></div><div class="part-tray">${craftParts.map(([id,name,caption])=>`<button draggable="true" data-action="craft-part" data-part="${id}" class="part-card ${installedParts.has(id)?'installed':''} ${selectedPart===id?'chosen':''}" aria-pressed="${selectedPart===id}" ${installedParts.has(id)?'disabled':''}><i>${({eyes:'◉',pompom:'✿',mirror:'◇',whiskers:'〰',fur:'✧'})[id]}</i><span><b>${name}</b><small>${installedParts.has(id)?'已安装':caption}</small></span>${installedParts.has(id)?'<em>✓</em>':''}</button>`).join('')}</div><div class="craft-lore" title="民俗知识提示：狮头工艺与寓意因地区、作坊和师承各有差异。"><span>✦</span><p>眉眼、额饰与须髯共同塑造狮头神态；不同流派的装饰和寓意各有传承。</p></div>`:''}<div class="craft-panel-actions">${button('← 上一步','craft-prev','craft-secondary',craft===0?'disabled':'')}${craft<3?button('下一步 →','craft-next','craft-primary'):button('保存我的狮头 PNG ↓','download-lion','craft-primary',installedParts.size<5?'disabled':'')}</div><p class="craft-sound-note">点击步骤可听见本段制作提示音</p></aside></section><p class="craft-footnote">${c.tip}　${ref('craft')}</p></section>`;}
const moves=[['look','抬头','1'],['shake','摇头','2'],['mouth','开口','3'],['bow','行礼','4'],['jump','跃起','空格'],['walk','迈步','→']];
function drumsPage(){const keys=[['D','低音鼓','A'],['H','高音鼓','S'],['G','小锣','D'],['C','钹','J'],['B','重击锣','K']];return `<section class="drum-experience"><div class="drum-heading"><span class="eyebrow">04 / RHYTHM · LION AWAKENING</span><h1>鼓起狮醒</h1><p>敲下你的节奏，让狮子听见。</p></div><section class="drum-theater" id="drum-theater" data-mood="idle" aria-label="醒狮鼓点互动舞台"><div class="theater-stars" aria-hidden="true"><i>✦</i><i>✧</i><i>✦</i><i>✧</i></div><div class="theater-caption"><span>醒狮鼓 · 佛山红</span><b id="drum-response" aria-live="polite">等你敲响第一声</b></div><div class="drum-halo" aria-hidden="true"></div><div class="stage-drum"><img src="/lion/drum-3d.webp" alt="红金纹样、立体桶身与木架的醒狮鼓" fetchpriority="high"><span class="drum-pulse"></span><span class="drum-pulse second"></span></div><div class="stage-lion" aria-hidden="true"><div class="lion-sprite"></div><span class="lion-shadow"></span></div><div class="theater-cloud cloud-one">☁</div><div class="theater-cloud cloud-two">☁</div><div class="theater-sparks" aria-hidden="true"></div><div class="stage-floor"></div><div class="combo-meter"><i id="combo-fill"></i></div><div class="stage-footnote"><span>连击 <b id="combo-count">0</b></span><span>击鼓越密，狮意越浓</span><span id="active-instrument">READY</span></div></section><div class="drum-controls"><div class="instrument-row" role="group" aria-label="醒狮鼓点键盘"><span class="keyboard-hint">敲击键盘或点击鼓键</span>${keys.map(([id,name,key])=>`<button class="instrument-key" data-action="hit" data-key="${id}" data-physical="${key}" aria-label="${name}，键盘${key}"><kbd>${key}</kbd><b>${name}</b><i></i></button>`).join('')}</div><div class="drum-footer"><p><span class="status-dot"></span> 低音起势 · 高音应和 · 锣钹收尾</p><label class="volume-control">音量 <input id="volume" aria-label="音量" type="range" min="0" max="100" value="${volume*100}"><output id="volume-value">${Math.round(volume*100)}%</output></label></div></div><details class="drum-patterns"><summary>听一段传统节奏灵感 <span>＋</span></summary><div class="pattern-row">${rhythms.map((r,i)=>`<button class="pattern-chip ${i===pattern?'selected':''}" data-action="pattern" data-index="${i}"><b>${r.name}</b><small>${r.mood}</small></button>`).join('')}<button class="pattern-play" data-action="play-rhythm">${playing?'Ⅱ 暂停':'▶ 示范'}</button></div><p>原创合成教学节奏，不代表传统狮队的固定鼓谱或实录。${ref('south')}</p></details>${drumCultureMarkup()}</section>`;}
function agentPage(){return `<section class="agent-experience"><div class="agent-heading"><span class="eyebrow">05 / MULTIMODAL LION GUIDE</span><h1>看一只狮，<em>问一段故事。</em></h1><p>文字、狮头照片或语音提问；AI 结合可核验的非遗资料回答。</p></div><section class="agent-workspace"><p id="signin-note" class="quiet-note" ${signedIn!==false?'hidden':''}>AI 导览需要登录。<a href="/signin-with-chatgpt?return_to=%2F%23agent" target="_top">登录后开始 ↗</a></p><div class="agent-console"><div class="agent-console-top"><span><i class="status-dot"></i> 狮遇 · 多模态 AI 导览</span><small id="agent-status">${configured===false?'AI 暂未配置，仍可检索资料':'文字 · 图片 · 语音转文字 · 资料检索'}</small></div><div class="agent-stage">${!agent.result&&!agent.busy?`<div class="agent-welcome"><span class="agent-orbit" aria-hidden="true"><i>狮</i></span><h2>今天想了解什么？</h2><p>提问、说出问题，或上传一张狮头照片开始对话。</p><div class="agent-prompt-title"><span>试试这样提问</span><small>START WITH A QUESTION</small></div><div class="prompt-chips">${['南狮和北狮有什么区别？','狮头是怎样制作的？','这三种教学鼓点有什么区别？','帮我看看这张狮头图'].map((q,i)=>button(q,'prompt','',`data-index="${i}"`)).join('')}</div></div>`:''}${agent.error?`<p class="error" role="alert">${esc(agent.error)}</p>`:''}${agent.busy?`<div class="agent-loading" role="status"><span class="spinner"></span>正在理解问题、检索资料并选择工具…</div>`:''}${agent.result?resultHTML(agent.result):''}${agent.history.length?`<details class="work-note"><summary>本次对话 · ${agent.history.length} 轮 <span>＋</span></summary>${agent.history.slice(0,-1).map(x=>`<p><b>${esc(x.question)}</b></p><p class="answer-text">${esc(x.answer)}</p>`).join('')}${button('清空本次对话','clear-chat','secondary',agent.busy?'disabled':'')}</details>`:''}</div><div class="composer"><textarea id="question" maxlength="1600" placeholder="输入关于醒狮的问题，或描述你上传的图片……" aria-label="向非遗 Agent 提问" ${agent.busy?'disabled':''}>${esc(agent.question)}</textarea>${agent.image?`<div class="upload-preview"><img src="${agent.image}" alt="待分析的狮头图片"><span>${esc(agent.name)}</span>${button('移除 ×','remove-image','text-button',agent.busy?'disabled':'')}</div>`:''}<div class="composer-bottom"><label class="upload-button">＋ 上传狮头图片<input id="image-upload" type="file" accept="image/jpeg,image/png,image/webp" ${agent.busy?'disabled':''}></label>${button(agent.listening?'停止语音':'语音输入 ◉','voice-input','voice-button',agent.busy?'disabled':'')}<span class="composer-tip">语音由浏览器转成文字后发送</span>${button(agent.busy?'停止生成':'发送提问 ↗',agent.busy?'cancel-agent':'send-agent','primary')}</div></div><p class="quiet-note agent-note">图片判断会说明可见依据与不确定性；仅凭照片无法确认产地、师承或内部材料。</p></div></section></section>`;}
function resultHTML(r){const toolNames={plan:'意图与计划',search_heritage:'RAG 检索',get_region:'地区知识工具',get_craft_step:'工艺知识工具',get_rhythm:'鼓点知识工具',rejected:'安全拦截',validate:'输出校验',compose:'生成回答',fallback:'资料兜底'};const statuses={ok:'完成',rejected:'已拦截',fallback:'兜底'};return `<article class="agent-result"><div class="result-top"><span class="eyebrow">${r.source==='ai'?'AI 导览 · 资料增强':'资料检索 · 本次未完成 AI 生成'}</span><div>${button('朗读 / 停止','speak','text-button')}${button('保存讲解 ↓','save-answer','text-button')}</div></div>${r.notice?`<p class="notice">${esc(r.notice)}</p>`:''}${r.candidate?`<h2>${esc(r.candidate)}</h2>`:''}${r.observations?.length?`<div class="feature-tags">${r.observations.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}<div class="answer-text">${esc(r.answer)}</div>${r.uncertainty?.length?`<div class="uncertainty">${r.uncertainty.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}<div class="actions">${r.actions.map((a,i)=>button(esc(a.label)+' ↗','agent-scene','secondary',`data-index="${i}"`)).join('')}</div><details class="result-details"><summary>答辩依据 · 查看本次 Agent 工作流</summary><div class="audit-grid"><p><b>大模型</b><span>低温生成（0.2）＋JSON结构解析＋字段白名单验收</span></p><p><b>Agent工作流</b><span>意图计划 → 模型自主工具调用 → 生成与校验；记录实际调用</span></p><p><b>RAG</b><span>中文关键词扩展，标题、标签、正文加权取前5条；答案引用可打开</span></p><p><b>多模态</b><span>文字＋图片视觉模型＋浏览器语音转文字；此轮记录实际输入类型</span></p><p><b>安全可控</b><span>登录、同源、限流、图片校验；图片结论保留观察依据与不确定性</span></p><p><b>工具集成</b><span>Function Calling连接地区、工艺、鼓点工具；参数与跳转目标双重白名单</span></p></div><div class="source-list">${r.documents.map(d=>ref(d.source)).join('')}</div><ol>${r.trace.map(t=>`<li><b>${esc(toolNames[t.tool]||t.tool)} · ${esc(statuses[t.status]||'记录')}</b><span>${esc(t.detail)}</span></li>`).join('')}</ol><p class="audit-note">引用链接对应上方公开资料；工具记录只显示实际执行的检索、调用与校验事件，不展示模型隐式推理。</p></details></article>`;}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function craftSound(step){
 try{
  const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;craftAudio??=new AC();const ctx=craftAudio;if(ctx.state==='suspended')ctx.resume();
  const noise=(start,duration,low,high,level)=>{const buffer=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*duration),ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const src=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();src.buffer=buffer;filter.type='bandpass';filter.frequency.setValueAtTime(low,start);filter.frequency.exponentialRampToValueAtTime(Math.max(low,high),start+duration);filter.Q.value=.7;gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(level,start+.025);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);src.connect(filter).connect(gain).connect(ctx.destination);src.start(start);src.stop(start+duration);};
  const note=(hz,start,duration,level,type='sine')=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=type;osc.frequency.setValueAtTime(hz,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(level,start+.025);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(gain).connect(ctx.destination);osc.start(start);osc.stop(start+duration);};
  const t=ctx.currentTime;
  if(step===0){noise(t,.2,180,650,.035);note(145,t,.13,.025,'triangle');note(190,t+.17,.12,.018,'triangle');}
  else if(step===1){noise(t,.42,260,1500,.032);noise(t+.18,.3,350,1800,.022);}
  else if(step===2){noise(t,.18,900,2600,.018);note(740,t,.24,.025);note(988,t+.13,.26,.018);}
  else{noise(t,.16,480,1800,.018);note(659,t,.34,.025);note(880,t+.1,.4,.02);}
 }catch{}
}
function craftPoint(svg,event){const pt=svg.createSVGPoint();pt.x=event.clientX;pt.y=event.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse());return{x:p.x,y:p.y};}
function installCraftPart(slot,part=selectedPart){if(!part)return toast('先从右侧选择一件装饰。');if(part!==slot)return toast('这个位置不合适，试试另一个虚线标记。');if(installedParts.has(part))return;installedParts.add(part);selectedPart='';render();if(installedParts.size===5){craftSound(3);playPattern(['D','','G','C','D','','G','C','','D','G','C','','D','','G'],112,.42,()=>{},()=>{},{loops:1}).catch(()=>{});toast('五件装饰全部归位，狮头完成！');}else toast(`${craftParts.find(x=>x[0]===part)?.[1]}已吸附到位。`);}
async function downloadCraftPNG(){const svg=$('#craft-illustration');if(!svg)return;try{const clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width','1200');clone.setAttribute('height','1000');clone.style.setProperty('--craft-base',palette.color);clone.style.setProperty('--craft-ink',palette.color);clone.style.setProperty('--craft-accent',palette.accent);const bg=document.createElementNS('http://www.w3.org/2000/svg','rect');bg.setAttribute('width','600');bg.setAttribute('height','500');bg.setAttribute('fill','#080808');clone.insertBefore(bg,clone.firstChild);const source=new XMLSerializer().serializeToString(clone),url=URL.createObjectURL(new Blob([source],{type:'image/svg+xml;charset=utf-8'})),img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1000;const ctx=canvas.getContext('2d');ctx.fillStyle='#080808';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,1200,1000);ctx.strokeStyle='#bda36e';ctx.lineWidth=2;ctx.strokeRect(24,24,1152,952);ctx.fillStyle='#d7bd81';ctx.font='24px "Microsoft YaHei",sans-serif';ctx.textAlign='center';ctx.fillText(`狮遇 · ${heroTemplates.find(([n,c])=>c===palette.color)?.[0]||'我的醒狮'}`,600,955);URL.revokeObjectURL(url);canvas.toBlob(blob=>{if(blob){download(blob,'狮遇-我的狮头.png');toast('狮头 PNG 已保存。');}else toast('图片生成失败，请重试。');},'image/png');}catch{toast('图片生成失败，请重试。');}}
function beat(i){const type=rhythms[pattern].beats[i];if(type)reactToStrike(type,false);$$('.beat').forEach((el,j)=>el.classList.toggle('active',i===j));}
async function togglePlay(){try{if(recording){clearTimeout(practiceTimer);recording=null;}if(playing){stop();playing=false;render();return;}await enableAudio();if(page!=='drums')return;playing=true;render();playPattern(rhythms[pattern].beats,bpm,volume,beat,()=>{playing=false;if(page==='drums')render();},{loops:loop?0:1});}catch{toast('音频未能启动，请再次点击播放。');}}
let drumLastHit=0,drumCombo=0,drumHitCount=0,drumResetTimer;
function reactToStrike(key,fromUser=true){const now=performance.now(),gap=now-drumLastHit;drumCombo=gap<680?drumCombo+1:1;drumLastHit=now;drumHitCount++;const mood=key==='B'?'heavy':drumCombo>=5?'combo':gap<300?'fast':'light',stage=$('#drum-theater');if(!stage)return;stage.dataset.mood=mood;stage.classList.remove('react');void stage.offsetWidth;stage.classList.add('react');const label={D:'低音鼓',H:'高音鼓',G:'小锣',C:'钹',B:'重击锣'}[key]||'鼓点';$('#active-instrument').textContent=label;$('#drum-response').textContent={light:'狮子听见了',fast:'鼓点渐密，醒狮起舞',heavy:'重锣一响，雄狮抬头',combo:'好节奏！狮子越跳越欢'}[mood];$('#combo-count').textContent=drumCombo;$('#combo-fill').style.transform=`scaleX(${Math.min(1,drumCombo/8)})`;const button=$(`[data-key="${key}"]`);if(button){button.classList.add('pressed');setTimeout(()=>button.classList.remove('pressed'),180);}if(fromUser&&mood==='heavy'&&navigator.vibrate)navigator.vibrate(36);if(mood==='combo'||(drumCombo>=4&&drumHitCount%4===0))burstSparks();clearTimeout(drumResetTimer);drumResetTimer=setTimeout(()=>{if($('#drum-theater')){$('#drum-theater').dataset.mood='idle';$('#drum-theater').classList.remove('react');$('#drum-response').textContent='等你敲响下一声';}},1400);}
function burstSparks(){const layer=$('.theater-sparks');if(!layer)return;for(let i=0;i<9;i++){const p=document.createElement('i');p.textContent=i%3?'✦':'☁';p.style.setProperty('--spark-x',`${(Math.random()-.5)*300}px`);p.style.setProperty('--spark-y',`${-50-Math.random()*170}px`);layer.append(p);setTimeout(()=>p.remove(),1100);}}
async function strike(key){try{await hit(key,volume);reactToStrike(key);if(recording?.started)recording.events.push({type:key,time:(performance.now()-recording.start)/1000});}catch{toast('请点击页面以启用声音。');}}
async function practiceRhythm(){if(recording){clearTimeout(practiceTimer);recording=null;render();return;}stop();playing=false;await enableAudio();if(page!=='drums')return;recording={events:[],beats:[...rhythms[pattern].beats],bpm,start:0,started:false};lastScore=null;render();let count=4;const tick=()=>{if(!recording)return;if(count){$('#practice-status').textContent=`预备 ${count}…`;hit('D',volume*.45);count--;practiceTimer=setTimeout(tick,60000/bpm);}else{recording.started=true;recording.start=performance.now();$('#practice-status').textContent='开始！按谱敲完两个小节。';let i=0;const mark=()=>{if(!recording)return;beat(i++);if(i<16)practiceTimer=setTimeout(mark,60000/bpm/2);else practiceTimer=setTimeout(finishPractice,60000/bpm/2+190);};mark();}};tick();}
function finishPractice(){if(!recording)return;lastScore=scoreRhythm(recording.events,recording.beats,recording.bpm);saved.rhythm.push({date:Date.now(),pattern:rhythms[pattern].id,...lastScore});saved.rhythm=saved.rhythm.slice(-30);save();recording=null;render();}
async function upload(file){if(!file)return;const token=++agent.upload;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){agent.error='请选择不超过 8 MB 的 JPG、PNG 或 WebP 图片。';render();return;}const u=URL.createObjectURL(file);try{const img=new Image();img.src=u;await img.decode();if(img.width*img.height>40000000)throw Error('尺寸过大');const scale=Math.min(1,1400/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);const data=c.toDataURL('image/jpeg',.85);if(data.length>1600000)throw Error('压缩后仍过大');if(token!==agent.upload)return;agent.image=data;agent.name=file.name;agent.error='';render();}catch{if(token===agent.upload){agent.error='图片无法读取或尺寸过大，请换一张清晰的狮头照片。';render();}}finally{URL.revokeObjectURL(u);}}
function toggleVoice(){if(agent.listening){voiceRecognition?.stop?.();agent.listening=false;voiceRecognition=null;render();return;}const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){agent.error='当前浏览器不支持语音识别，请使用 Chrome 或直接输入文字。';render();return;}const recognition=new Speech();recognition.lang='zh-CN';recognition.continuous=false;recognition.interimResults=false;voiceRecognition=recognition;agent.listening=true;agent.error='';render();recognition.onresult=e=>{const text=[...e.results].map(x=>x[0]?.transcript||'').join('').trim();if(text)agent.question=[agent.question.trim(),text].filter(Boolean).join(' ');};recognition.onerror=e=>{if(e.error!=='aborted')agent.error=e.error==='not-allowed'?'麦克风权限未开启，请在浏览器地址栏允许使用麦克风。':'语音识别未完成，请重试或直接输入。';};recognition.onend=()=>{if(voiceRecognition===recognition){voiceRecognition=null;agent.listening=false;if(page==='agent')render();}};try{recognition.start();}catch{voiceRecognition=null;agent.listening=false;agent.error='无法启动语音识别，请重试。';render();}}
function validResult(r){return r&&['ai','reference'].includes(r.source)&&typeof r.answer==='string'&&Array.isArray(r.documents)&&r.documents.every(x=>sources[x.source])&&Array.isArray(r.trace)&&Array.isArray(r.actions)&&r.actions.every(x=>['regions','craft','drums'].includes(x.page));}
async function sendAgent(){if(agent.busy)return;if(!agent.question.trim()&&!agent.image){agent.error='输入一个问题，或上传一张狮头图片。';render();return;}const id=++agent.request;agent.busy=true;agent.error='';agent.controller=new AbortController();const timer=setTimeout(()=>agent.controller?.abort(),55000);render();try{const res=await fetch('/api/lion-agent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:agent.question,image:agent.image,history:agent.history.slice(-4)}),signal:agent.controller.signal});const r=await res.json();if(!res.ok)throw Error(r.message||'请求未完成，请重试。');if(!validResult(r))throw Error('服务返回格式不正确，请重试。');if(id!==agent.request)return;agent.result=r;agent.history.push({question:agent.question||'识别上传的狮头图片',answer:r.answer});agent.history=agent.history.slice(-8);}catch(e){if(id===agent.request)agent.error=e.name==='AbortError'?'本次请求超时或已停止，可以重试。':e.message;}finally{clearTimeout(timer);if(id===agent.request){agent.busy=false;render();}}}
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el||el.disabled)return;if(el.dataset.page){const target=el.dataset.page==='regions'?'history':el.dataset.page;go(target);if(el.dataset.page==='regions'||el.dataset.anchor)requestAnimationFrame(()=>document.getElementById('regional-lions')?.scrollIntoView({behavior:'smooth',block:'start'}));return;}const a=el.dataset.action,i=Number(el.dataset.index);switch(a){
 case 'sources':go('home');$('#work-note').open=true;$('#work-note').scrollIntoView({behavior:'smooth'});break;
 case 'lion-legend':openLegend(i);break;case 'close-legend':$('#lion-dialog')?.close();break;
 case 'start-drums':go('drums');break;case 'start-agent':go('agent');break;
 case 'era':era=i;render();break;case 'era-prev':era=Math.max(0,era-1);render();break;case 'era-next':era=Math.min(timeline.length-1,era+1);render();break;
 case 'craft':craft=i;selectedPart='';craftSound(craft);render();break;case 'craft-prev':craft=Math.max(0,craft-1);selectedPart='';craftSound(craft);render();break;case 'craft-next':craft=Math.min(3,craft+1);selectedPart='';craftSound(craft);render();break;
 case 'craft-ink':craftInk=el.dataset.color;craftTemplate=-1;render();break;case 'craft-template':{const [name,color,accent]=heroTemplates[i];palette={color,accent};craftInk=color;craftTemplate=i;render();toast(`${name}配色已应用。`);break;}case 'clear-paint':craftDrawing=[];render();break;
 case 'craft-part':selectedPart=selectedPart===el.dataset.part?'':el.dataset.part;render();break;case 'download-lion':await downloadCraftPNG();break;
 
 case 'pattern':stop();clearTimeout(practiceTimer);recording=null;playing=false;pattern=i;bpm=rhythms[i].bpm;lastScore=null;render();break;
 case 'play-rhythm':await togglePlay();break;case 'hit':await strike(el.dataset.key);break;case 'practice-rhythm':try{await practiceRhythm();}catch{toast('请再次点击，启用音频。');}break;
 case 'download-audio':el.disabled=true;try{download(await rhythmWav(rhythms[pattern].beats,bpm),`狮遇-${rhythms[pattern].name}-${bpm}BPM.wav`);}catch{toast('音频导出失败，请重试。');}finally{el.disabled=false;}break;

 case 'prompt':agent.question=el.textContent;render();$('#question').focus();break;case 'send-agent':await sendAgent();break;case 'voice-input':toggleVoice();break;case 'remove-image':agent.upload++;agent.image='';agent.name='';render();break;
 case 'cancel-agent':agent.controller?.abort();agent.request++;agent.busy=false;render();break;case 'clear-chat':agent.result=null;agent.history=[];agent.question='';agent.image='';agent.name='';agent.upload++;render();break;
 case 'agent-scene':{const x=agent.result.actions[i],lists={regions,craft:craftSteps,drums:rhythms},idx=lists[x.page]?.findIndex(t=>t.id===x.target);if(idx<0||idx===undefined)return;if(x.page==='regions'){go('history');requestAnimationFrame(()=>document.getElementById(`region-${x.target}`)?.scrollIntoView({behavior:'smooth',block:'center'}));break;}if(x.page==='craft')craft=idx;if(x.page==='drums'){pattern=idx;bpm=rhythms[idx].bpm;}go(x.page);break;}
 case 'speak':if(!window.speechSynthesis){toast('此浏览器不支持朗读。');break;}if(speechSynthesis.speaking){speechSynthesis.cancel();break;}const speech=new SpeechSynthesisUtterance(agent.result.answer);speech.lang='zh-CN';speech.onerror=()=>toast('朗读未完成，请检查浏览器语音支持。');speechSynthesis.speak(speech);break;
 case 'save-answer':download(new Blob([agent.result.answer+'\n\n'+agent.result.documents.map(d=>sources[d.source].name+' '+sources[d.source].url).join('\n')],{type:'text/plain;charset=utf-8'}),'狮遇-AI讲解.txt');break;
 }});
document.addEventListener('input',e=>{if(e.target.id==='question')agent.question=e.target.value;if(e.target.id==='paper-progress'){progress=Number(e.target.value);$('#paper-value').textContent=progress+' 层';const shell=$('.paper-shell');if(shell)shell.style.opacity=String(progress/5);$$('.paper-count i').forEach((x,i)=>x.classList.toggle('on',i<progress));$('.craft-mini-note').textContent=`裱纸 ${progress} / 5 层`;}if(e.target.id==='bpm'){bpm=Number(e.target.value);$('#bpm-value').textContent=bpm+' BPM';}if(e.target.id==='volume'){volume=Number(e.target.value)/100;$('#volume-value').textContent=Math.round(volume*100)+'%';}});
document.addEventListener('change',e=>{if(e.target.id==='image-upload')upload(e.target.files[0]);if(['bpm','volume','loop'].includes(e.target.id)){if(e.target.id==='loop')loop=e.target.checked;if(recording){clearTimeout(practiceTimer);recording=null;render();}if(playing){stop();playing=false;togglePlay();}}});
document.addEventListener('click',e=>{const slot=e.target.closest('#craft-illustration [data-slot]');if(slot&&page==='craft'&&craft===3)installCraftPart(slot.dataset.slot);});
document.addEventListener('dragstart',e=>{const part=e.target.closest('[data-part]');if(!part||page!=='craft'||craft!==3)return;e.dataTransfer.setData('text/plain',part.dataset.part);e.dataTransfer.effectAllowed='move';part.classList.add('dragging');});
document.addEventListener('dragend',e=>{const part=e.target.closest('[data-part]');if(part){part.classList.remove('dragging');part.animate([{transform:'scale(.92)',opacity:.55},{transform:'scale(1)',opacity:1}],{duration:220,easing:'ease-out'});}});
document.addEventListener('dragover',e=>{const slot=e.target.closest('#craft-illustration [data-slot]');if(slot){e.preventDefault();e.dataTransfer.dropEffect='move';slot.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>e.target.closest('#craft-illustration [data-slot]')?.classList.remove('drag-over'));
document.addEventListener('drop',e=>{const slot=e.target.closest('#craft-illustration [data-slot]');if(slot){e.preventDefault();slot.classList.remove('drag-over');installCraftPart(slot.dataset.slot,e.dataTransfer.getData('text/plain'));}});
document.addEventListener('pointerdown',e=>{const svg=e.target.closest('#craft-illustration');if(!svg||page!=='craft')return;if(craft===2){const p=craftPoint(svg,e);activeCraftPath={color:craftInk,width:7,points:`M${p.x.toFixed(1)} ${p.y.toFixed(1)}`};craftDrawing.push(activeCraftPath);const layer=svg.querySelector('.drawing-layer');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',activeCraftPath.points);path.setAttribute('stroke',craftInk);path.setAttribute('stroke-width','7');path.setAttribute('fill','none');path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');layer?.append(path);activeCraftPath.element=path;svg.setPointerCapture(e.pointerId);e.preventDefault();}else if(craft===1){progress=Math.min(5,progress+1);const range=$('#paper-progress');if(range)range.value=String(progress);$('#paper-value').textContent=`${progress} 层`;const shell=$('.paper-shell');if(shell)shell.style.opacity=String(progress/5);$$('.paper-count i').forEach((x,i)=>x.classList.toggle('on',i<progress));$('.craft-mini-note').textContent=`裱纸 ${progress} / 5 层`;}});
document.addEventListener('pointermove',e=>{if(!activeCraftPath||page!=='craft')return;const svg=$('#craft-illustration');if(!svg)return;const p=craftPoint(svg,e);activeCraftPath.points+=` L${p.x.toFixed(1)} ${p.y.toFixed(1)}`;activeCraftPath.element?.setAttribute('d',activeCraftPath.points);});
document.addEventListener('pointerup',()=>{activeCraftPath=null;});
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.target.closest('input,textarea,select,[contenteditable]'))return;if(page==='drums'){const key={'a':'D','s':'H','d':'G','j':'C','k':'B'}[e.key.toLowerCase()];if(key){e.preventDefault();strike(key);}}});
window.addEventListener('hashchange',()=>go(location.hash.slice(1)));document.addEventListener('visibilitychange',()=>{if(document.hidden){cleanup();render();}});window.addEventListener('pagehide',cleanup);render();
